# Enterprise E-Commerce Checkout Orchestrator in C#

Below is a modular architecture for an enterprise-grade checkout system in C# that integrates validation, transaction orchestration, and invoice generation.

## Architecture Overview

```
┌───────────────────────────────────────────────────────────────────────────────┐
│                        E-Commerce Checkout Orchestrator                     │
├───────────────────┬───────────────────┬───────────────────┬───────────────────┤
│   Shopping Cart   │  Saga Coordinator │  Invoice Generator│  External       │
│    Validation     │                   │                   │  Services       │
│   Engine          │                   │                   │   (Microservices)│
└───────────┬───────┴───────┬───────────┴───────┬───────────┴───────┬───────────┘
            │               │                   │                   │
            ▼               ▼                   ▼                   ▼
┌───────────────────┐ ┌───────────────────┐ ┌───────────────────┐ ┌───────────────────┐
│   Cart Validation │ │  Saga Orchestrator│ │   PDF Invoice     │ │ Inventory        │
│ - Item availability│ │ - Payment        │ │ - Billing        │ │ - Stock updates   │
│ - Price consistency│ │ - Shipping       │ │   statements     │ │ - Reserved        │
│ - Quantity checks  │ │ - Order status   │ │ - Tax calculations│ │   inventory      │
└───────────────────┘ │ - Compensating   │ └───────────────────┘ └───────────────────┘
                      │   transactions    │
                      └───────────────────┘
```

## Implementation

### 1. Shopping Cart Validation Engine

```csharp
public interface IShoppingCartValidator
{
    Task<ValidationResult> ValidateCartAsync(Cart cart);
}

public class ShoppingCartValidator : IShoppingCartValidator
{
    private readonly IItemAvailabilityService _itemAvailabilityService;
    private readonly IPriceService _priceService;
    private readonly IInventoryService _inventoryService;

    public ShoppingCartValidator(
        IItemAvailabilityService itemAvailabilityService,
        IPriceService priceService,
        IInventoryService inventoryService)
    {
        _itemAvailabilityService = itemAvailabilityService;
        _priceService = priceService;
        _inventoryService = inventoryService;
    }

    public async Task<ValidationResult> ValidateCartAsync(Cart cart)
    {
        var validationResult = new ValidationResult();

        foreach (var cartItem in cart.Items)
        {
            // Check item availability
            var availability = await _itemAvailabilityService.CheckAvailabilityAsync(cartItem.ProductId);
            if (!availability.IsAvailable)
            {
                validationResult.AddError(cartItem.ProductId,
                    $"Product {cartItem.ProductId} is out of stock");
                continue;
            }

            // Check price consistency
            var currentPrice = await _priceService.GetCurrentPriceAsync(cartItem.ProductId);
            if (currentPrice != cartItem.Price)
            {
                validationResult.AddError(cartItem.ProductId,
                    $"Price changed from {cartItem.Price} to {currentPrice}");
            }

            // Check quantity against inventory
            var inventory = await _inventoryService.GetInventoryAsync(cartItem.ProductId);
            if (inventory.Quantity < cartItem.Quantity)
            {
                validationResult.AddError(cartItem.ProductId,
                    $"Only {inventory.Quantity} items available (requested {cartItem.Quantity})");
            }
        }

        return validationResult;
    }
}

public class ValidationResult
{
    public bool IsValid => !Errors.Any();
    public List<(Guid ProductId, string Message)> Errors { get; } = new();

    public void AddError(Guid productId, string message)
    {
        Errors.Add((productId, message));
    }
}
```

### 2. Saga Transaction Coordinator

```csharp
public interface ICheckoutSaga
{
    Task<CheckoutResult> ExecuteAsync(Cart cart, Customer customer);
}

public class CheckoutSaga : ICheckoutSaga, IDisposable
{
    private readonly IOrderRepository _orderRepository;
    private readonly IPaymentService _paymentService;
    private readonly IShippingService _shippingService;
    private readonly IInventoryService _inventoryService;
    private readonly IInvoiceGenerator _invoiceGenerator;
    private readonly IEmailService _emailService;

    private readonly List<Action> _compensatingActions = new();
    private Order _currentOrder;

    public async Task<CheckoutResult> ExecuteAsync(Cart cart, Customer customer)
    {
        try
        {
            // Create order header
            _currentOrder = new Order
            {
                CustomerId = customer.Id,
                OrderDate = DateTime.UtcNow,
                Status = OrderStatus.Pending,
                Items = cart.Items.Select(i => new OrderItem
                {
                    ProductId = i.ProductId,
                    Quantity = i.Quantity,
                    UnitPrice = i.Price
                }).ToList()
            };

            await _orderRepository.AddAsync(_currentOrder);
            _compensatingActions.Add(() => _orderRepository.Delete(_currentOrder.Id));

            // Reserve inventory
            var inventoryReservations = new List<InventoryReservation>();
            foreach (var item in cart.Items)
            {
                var reservation = await _inventoryService.ReserveInventoryAsync(
                    item.ProductId, item.Quantity, _currentOrder.Id);
                inventoryReservations.Add(reservation);
                _compensatingActions.Add(() => _inventoryService.ReleaseReservation(reservation.Id));
            }

            // Process payment
            var paymentResult = await _paymentService.ProcessPaymentAsync(
                _currentOrder.Id, cart.TotalAmount, customer.PaymentMethod);
            if (!paymentResult.Success)
            {
                throw new CheckoutException("Payment failed", paymentResult.ErrorMessage);
            }
            _currentOrder.PaymentStatus = paymentResult.Status;
            _compensatingActions.Add(() => _paymentService.RefundPayment(_currentOrder.Id));

            // Create shipping
            var shipping = await _shippingService.CreateShippingAsync(
                _currentOrder.Id, customer.ShippingAddress);
            _currentOrder.ShippingId = shipping.Id;
            _compensatingActions.Add(() => _shippingService.CancelShipping(shipping.Id));

            // Update order status
            _currentOrder.Status = OrderStatus.Completed;
            await _orderRepository.UpdateAsync(_currentOrder);

            // Generate invoice
            var invoice = await _invoiceGenerator.GenerateInvoiceAsync(_currentOrder);
            await _emailService.SendInvoiceAsync(customer.Email, invoice);

            return new CheckoutResult
            {
                Success = true,
                OrderId = _currentOrder.Id,
                Invoice = invoice
            };
        }
        catch (Exception ex)
        {
            // Execute compensating transactions
            await ExecuteCompensatingActionsAsync();
            throw new CheckoutException("Checkout failed", ex.Message);
        }
    }

    private async Task ExecuteCompensatingActionsAsync()
    {
        foreach (var action in _compensatingActions)
        {
            try
            {
                action();
            }
            catch (Exception ex)
            {
                // Log compensation failure
                Console.WriteLine($"Compensation failed: {ex.Message}");
            }
        }
    }

    public void Dispose()
    {
        _compensatingActions.Clear();
    }
}
```

### 3. Invoice Generator

```csharp
public interface IInvoiceGenerator
{
    Task<Invoice> GenerateInvoiceAsync(Order order);
}

public class PdfInvoiceGenerator : IInvoiceGenerator
{
    private readonly IInvoiceTemplateService _templateService;
    private readonly ILogger<PdfInvoiceGenerator> _logger;

    public PdfInvoiceGenerator(
        IInvoiceTemplateService templateService,
        ILogger<PdfInvoiceGenerator> logger)
    {
        _templateService = templateService;
        _logger = logger;
    }

    public async Task<Invoice> GenerateInvoiceAsync(Order order)
    {
        try
        {
            // Load template
            var template = await _templateService.GetTemplateAsync();

            // Prepare data
            var invoiceData = new InvoiceData
            {
                Header = new InvoiceHeader
                {
                    OrderId = order.Id,
                    OrderDate = order.OrderDate,
                    CustomerName = order.Customer.Name,
                    CustomerAddress = order.Customer.ShippingAddress,
                    TotalAmount = order.TotalAmount,
                    TaxAmount = order.TaxAmount,
                    ShippingCost = order.ShippingCost
                },
                Items = order.Items.Select(item => new InvoiceItem
                {
                    ProductId = item.ProductId,
                    ProductName = item.ProductName,
                    Quantity = item.Quantity,
                    UnitPrice = item.UnitPrice,
                    LineTotal = item.Quantity * item.UnitPrice
                }).ToList()
            };

            // Generate PDF
            var pdfBytes = await _templateService.RenderTemplateAsync(template, invoiceData);

            return new Invoice
            {
                OrderId = order.Id,
                PdfContent = pdfBytes,
                GeneratedDate = DateTime.UtcNow,
                Status = InvoiceStatus.Generated
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to generate invoice for order {OrderId}", order.Id);
            throw;
        }
    }
}
```

## Supporting Interfaces and Models

```csharp
// Cart Model
public class Cart
{
    public Guid Id { get; set; }
    public List<CartItem> Items { get; set; } = new();
    public decimal TotalAmount => Items.Sum(i => i.Quantity * i.Price);
}

// Order Models
public class Order
{
    public Guid Id { get; set; }
    public Guid CustomerId { get; set; }
    public DateTime OrderDate { get; set; }
    public OrderStatus Status { get; set; }
    public string PaymentStatus { get; set; }
    public string ShippingId { get; set; }
    public List<OrderItem> Items { get; set; } = new();
    public decimal TotalAmount => Items.Sum(i => i.Quantity * i.UnitPrice);
    public decimal TaxAmount { get; set; }
    public decimal ShippingCost { get; set; }
}

public class OrderItem
{
    public Guid ProductId { get; set; }
    public string ProductName { get; set; }
    public int Quantity { get; set; }
    public decimal UnitPrice { get; set; }
}

// Invoice Model
public class Invoice
{
    public Guid OrderId { get; set; }
    public byte[] PdfContent { get; set; }
    public DateTime GeneratedDate { get; set; }
    public InvoiceStatus Status { get; set; }
}

public enum InvoiceStatus
{
    Generated,
    Sent,
    Failed
}

// Checkout Result
public class CheckoutResult
{
    public bool Success { get; set; }
    public Guid OrderId { get; set; }
    public Invoice Invoice { get; set; }
    public string ErrorMessage { get; set; }
}

// Enums
public enum OrderStatus
{
    Pending,
    Processing,
    Completed,
    Failed,
    Cancelled
}
