## Dependency Injection Setup

```csharp
public static class CheckoutModule
{
    public static IServiceCollection AddCheckoutModule(this IServiceCollection services)
    {
        // Validation
        services.AddScoped<IShoppingCartValidator, ShoppingCartValidator>();
        services.AddScoped<IItemAvailabilityService, ItemAvailabilityService>();
        services.AddScoped<IPriceService, PriceService>();
        services.AddScoped<IInventoryService, InventoryService>();

        // Saga
        services.AddScoped<ICheckoutSaga, CheckoutSaga>();
        services.AddScoped<IPaymentService, PaymentService>();
        services.AddScoped<IShippingService, ShippingService>();
        services.AddScoped<IOrderRepository, OrderRepository>();

        // Invoice
        services.AddScoped<IInvoiceGenerator, PdfInvoiceGenerator>();
        services.AddScoped<IInvoiceTemplateService, InvoiceTemplateService>();
        services.AddScoped<IEmailService, EmailService>();

        // Compensation
        services.AddScoped<IDisposable>(provider =>
            new CheckoutSaga(
                provider.GetRequiredService<IOrderRepository>(),
                provider.GetRequiredService<IPaymentService>(),
                provider.GetRequiredService<IShippingService>(),
                provider.GetRequiredService<IInventoryService>(),
                provider.GetRequiredService<IInvoiceGenerator>(),
                provider.GetRequiredService<IEmailService>()
            ));

        return services;
    }
}
```

## Usage Example

```csharp
public class CheckoutController : ControllerBase
{
    private readonly ICheckoutSaga _checkoutSaga;
    private readonly IShoppingCartValidator _cartValidator;

    public CheckoutController(
        ICheckoutSaga checkoutSaga,
        IShoppingCartValidator cartValidator)
    {
        _checkoutSaga = checkoutSaga;
        _cartValidator = cartValidator;
    }

    [HttpPost("checkout")]
    public async Task<IActionResult> Checkout([FromBody] CheckoutRequest request)
    {
        // Validate cart
        var validationResult = await _cartValidator.ValidateCartAsync(request.Cart);
        if (!validationResult.IsValid)
        {
            return BadRequest(new { Errors = validationResult.Errors });
        }

        try
        {
            // Execute checkout saga
            var result = await _checkoutSaga.ExecuteAsync(request.Cart, request.Customer);

            if (result.Success)
            {
                return Ok(new { OrderId = result.OrderId, Invoice = result.Invoice });
            }

            return BadRequest(result.ErrorMessage);
        }
        catch (CheckoutException ex)
        {
            return StatusCode(500, new { Error = ex.Message });
        }
    }
}

public class CheckoutRequest
{
    public Cart Cart { get; set; }
    public Customer Customer { get; set; }
}
```

## Key Features

1. **Modular Design**: Each component has a single responsibility
2. **Saga Pattern**: Ensures eventual consistency across microservices
3. **Compensating Transactions**: Automatically rolls back partial transactions
4. **Validation**: Comprehensive cart validation before processing
5. **Invoice Generation**: Professional PDF invoicing
6. **Error Handling**: Graceful failure with compensation
7. **Dependency Injection**: Clean architecture with DI

This implementation provides a robust foundation for an enterprise e-commerce checkout system that can be extended with additional features like:
- Discount validation
- Subscription management
- Multi-currency support
- Advanced analytics
- Fraud detection integration
